CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE players (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, full_name text NOT NULL, jersey_number integer CHECK(jersey_number BETWEEN 0 AND 99), position text, generation text, photo_url text, is_public boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE competitions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, season text NOT NULL);
CREATE TABLE matches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), competition_id uuid REFERENCES competitions(id), opponent text NOT NULL, kickoff_at timestamptz, venue text, home boolean NOT NULL DEFAULT true, goals_for integer CHECK(goals_for >= 0), goals_against integer CHECK(goals_against >= 0), penalties_for integer CHECK(penalties_for >= 0), penalties_against integer CHECK(penalties_against >= 0), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','scheduled','finished','postponed')), published_at timestamptz);
CREATE TABLE match_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), match_id uuid NOT NULL REFERENCES matches(id) ON DELETE CASCADE, player_id uuid REFERENCES players(id), minute integer CHECK(minute BETWEEN 0 AND 150), event_type text NOT NULL CHECK(event_type IN ('goal','assist','yellow_card','red_card','substitution_in','substitution_out')));
CREATE TABLE articles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, title text NOT NULL, excerpt text, body text NOT NULL, cover_url text, published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE partners (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, tier text NOT NULL CHECK(tier IN ('gold','silver','bronze','community')), website_url text, logo_url text, published boolean NOT NULL DEFAULT false);
CREATE TABLE media_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), object_key text NOT NULL UNIQUE, alt_text text NOT NULL, mime_type text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor_id text NOT NULL, action text NOT NULL, resource_type text NOT NULL, resource_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_matches_kickoff ON matches(kickoff_at DESC);
CREATE INDEX idx_articles_published ON articles(published_at DESC) WHERE published_at IS NOT NULL;
